defmodule Switchboard.Tools.Doc do
  @moduledoc "Renders `docs/TOOLS.md` from the tool and workflow registries."

  alias Switchboard.{Controls, Tools, Workflows}

  @path "docs/TOOLS.md"

  def path, do: @path

  @doc "The Markdown for every registered tool (test-only tools excluded)."
  def render do
    tools = Enum.reject(Tools.all(), &test_tool?/1)

    """
    # Tools

    <!-- Generated by `mix switchboard.gen.tools_doc` from the registry. Do not edit by hand. -->

    Every tool runs through `Switchboard.Tools.run/3`: kill switch, read-only mode, a per-person
    rate limit, argument validation and an audit row. Write tools are annotated
    (`readOnlyHint: false`) and tell the agent to confirm with the user first; the watch tools
    (`watch_*`, `cancel_watch`) only change the caller's own watches, so the request is the
    confirmation. Rocket.Chat message text (`chat_*`) is untrusted: it never authorizes a write.

    | Tool | Kind | Connections | Default limit |
    |---|---|---|---|
    #{Enum.map_join(tools, "\n", &summary_row/1)}

    #{workflows()}
    #{Enum.map_join(tools, "\n", &section/1)}\
    """
  end

  defp workflows do
    mods = Workflows.all()

    """
    ## Workflows

    Team workflows chain several tools. Switchboard fetches the cheap facts first, with the
    person's own credentials (concurrently, with a time budget and **Notes** for systems that
    failed), then hands the agent numbered steps: what to present, what to check in the local
    checkout, which tools to call for detail, and which writes it may *propose*. A workflow never
    writes anything; every proposed write needs the user's OK of the exact change. Drafts for
    colleagues are in the person's language.

    Each workflow is an MCP prompt (a slash command: `/mcp__switchboard__<name>` in Claude Code)
    and can also be run with the [`workflow`](#workflow) tool, which returns the same text (Codex
    doesn't show MCP prompts). Both go through `Switchboard.Workflows.run/4`: a kill switch and a
    rate limit per workflow (`workflow:<name>` in the admin controls), argument checks and one
    audit row. In read-only mode a workflow still runs but offers no writes.

    | Workflow | Arguments | Reads | May propose | Default limit |
    |---|---|---|---|---|
    #{Enum.map_join(mods, "\n", &workflow_row/1)}

    #{Enum.map_join(mods, "\n", &workflow_section/1)}
    """
  end

  defp workflow_row(mod) do
    "| [`#{mod.name()}`](#workflow-#{mod.name()}) | #{workflow_args(mod)} | " <>
      "#{Enum.map_join(mod.connections(), ", ", &to_string/1)} | " <>
      "#{writes(mod)} | #{Controls.default_rate_limit(mod)}/min |"
  end

  defp title(mod) do
    t = mod.title()
    if String.ends_with?(t, ["?", "."]), do: t, else: t <> "."
  end

  defp workflow_args(mod) do
    case mod.arguments() do
      [] ->
        "none"

      args ->
        Enum.map_join(
          args,
          ", ",
          &if(&1.required, do: "`#{&1.name}`", else: "`#{&1.name}` (optional)")
        )
    end
  end

  defp writes(mod) do
    case mod.writes() do
      [] -> "nothing"
      list -> Enum.map_join(list, ", ", &"`#{&1}`")
    end
  end

  defp workflow_section(mod) do
    %{args: args, says: says} = mod.example()

    positional =
      Enum.map_join(mod.arguments(), "", &if(v = args[&1.name], do: " " <> v, else: ""))

    arguments =
      case mod.arguments() do
        [] ->
          "None."

        list ->
          Enum.map_join(list, "\n", fn a ->
            "- `#{a.name}`#{if a.required, do: "", else: " (optional)"}: #{a.description}"
          end)
      end

    """
    <a id="workflow-#{mod.name()}"></a>
    ### #{mod.name()}

    **#{title(mod)}** #{mod.description()}

    Arguments:

    #{arguments}

    Prefetches:

    #{Enum.map_join(mod.fetches(), "\n", &"- #{&1}")}

    May propose (each after the user's OK): #{writes(mod)}.

    - Claude Code: `/mcp__switchboard__#{mod.name()}#{positional}`
    - Any client: `workflow` with `#{Jason.encode!(%{"name" => mod.name(), "args" => args})}`, or just say "#{says}"
    """
  end

  defp test_tool?(mod), do: mod |> Module.split() |> Enum.take(2) == ["Switchboard", "TestTools"]

  defp summary_row(mod) do
    "| [`#{mod.name()}`](##{mod.name()}) | #{kind(mod)} | #{connections(mod)} | " <>
      "#{Switchboard.Controls.default_rate_limit(mod)}/min |"
  end

  defp kind(mod), do: if(mod.annotations()[:read_only], do: "read", else: "write")

  defp connections(mod) do
    case mod.connections() do
      [] -> "none"
      list -> Enum.map_join(list, ", ", &to_string/1)
    end
  end

  defp section(mod) do
    """
    ## #{mod.name()}

    **#{mod.title()}.** #{mod.description()}

    - Connections: #{connections(mod)}
    - Annotations: #{annotations(mod)}

    Arguments:

    #{arguments(mod.input_schema())}
    #{example(mod)}
    """
  end

  defp annotations(mod) do
    a = mod.annotations()

    [
      "readOnlyHint: #{a[:read_only] == true}",
      a[:destructive] != nil && "destructiveHint: #{a[:destructive]}",
      a[:idempotent] != nil && "idempotentHint: #{a[:idempotent]}",
      a[:open_world] != nil && "openWorldHint: #{a[:open_world]}"
    ]
    |> Enum.filter(& &1)
    |> Enum.map_join(", ", &"`#{&1}`")
  end

  defp arguments(%{"properties" => props} = schema) when map_size(props) > 0 do
    required = Map.get(schema, "required", [])

    rows =
      props
      |> Enum.sort_by(fn {k, _} -> {k not in required, k} end)
      |> Enum.map_join("\n", fn {name, spec} ->
        type = (spec["enum"] && Enum.map_join(spec["enum"], " \\| ", &"`#{&1}`")) || spec["type"]

        "| `#{name}` | #{type} | #{if name in required, do: "yes", else: "no"} | #{spec["description"] || ""} |"
      end)

    "| Name | Type | Required | Description |\n|---|---|---|---|\n" <> rows <> "\n"
  end

  defp arguments(_), do: "None.\n"

  defp example(mod) do
    if function_exported?(mod, :example, 0) do
      %{args: args, output: output} = mod.example()

      """
      Example call: `#{Jason.encode!(args)}`

      ````markdown
      #{String.trim_trailing(output)}
      ````
      """
    else
      ""
    end
  end
end
